export const envelope = [15, 18, 19];

export default function build(api) {
  const { size } = api;
  const SEAT_Y = 5;

  // Resolve palette from theme with robust fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:mossy_stone_bricks";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const roofStairs = api.theme?.roof?.stairs || stoneStairs;
  const roofSlab = api.theme?.roof?.slab || stoneSlab;
  const roofSolid = api.theme?.roof?.solid || stonePrimary;

  const woodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";

  const groundPavement = api.theme?.ground?.pavement || "minecraft:cobblestone";
  const groundPlinth = api.theme?.ground?.plinth || "minecraft:stone_bricks";
  const groundRevetment = api.theme?.ground?.revetment || "minecraft:mossy_cobblestone";
  const groundScree = api.theme?.ground?.scree || "minecraft:gravel";

  // Deterministic spatial hash for natural salt-spray weathering
  function hash(x, y, z) {
    let h = (x * 374761393 + y * 668265263 + z * 3141592653) ^ 0x5bf03635;
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      api.set(x, y, z, block);
    }
  }

  function getBase(blockStr) {
    return (blockStr || "minecraft:stone_bricks").split("[")[0];
  }

  function makeStair(blockStr, facing, half = "bottom") {
    const base = getBase(blockStr);
    return `${base}[facing=${facing},half=${half},shape=straight]`;
  }

  function makeSlab(blockStr, type = "bottom") {
    const base = getBase(blockStr);
    return `${base}[type=${type}]`;
  }

  function makeLog(blockStr, axis = "y") {
    const base = getBase(blockStr);
    return `${base}[axis=${axis}]`;
  }

  function getWallStone(x, y, z) {
    const h = hash(x, y, z);
    if (h < 0.42) return stonePrimary;
    if (h < 0.68) return stoneAccent;
    if (h < 0.84) return "minecraft:cobblestone";
    if (h < 0.94) return "minecraft:mossy_cobblestone";
    return "minecraft:cracked_stone_bricks";
  }

  function getFoundationStone(x, y, z) {
    const h = hash(x, y, z);
    if (h < 0.35) return groundPlinth;
    if (h < 0.65) return groundRevetment;
    if (h < 0.85) return "minecraft:cobblestone";
    return stonePrimary;
  }

  function getGroundBlock(x, y, z) {
    const h = hash(x, y, z);
    if (h < 0.35) return groundPavement;
    if (h < 0.60) return "minecraft:mossy_cobblestone";
    if (h < 0.78) return groundScree;
    if (h < 0.90) return "minecraft:cobblestone";
    return stoneAccent;
  }

  // 1. TERRAIN & FOUNDATION PASS (Rule 6: Follow the ground you are given)
  for (let x = 0; x < size[0]; x++) {
    for (let z = 0; z < size[2]; z++) {
      const h = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(size[1] - 1, Math.round(SEAT_Y + h)));

      // Fill solid foundation columns from terrain up to seat level
      for (let y = groundY; y < SEAT_Y; y++) {
        setBlock(x, y, z, getFoundationStone(x, y, z));
      }

      // Seat plane (y = SEAT_Y) ground surface
      const isInsideNave = x >= 4 && x <= 10 && z >= 4 && z <= 14;
      const isPath = x >= 6 && x <= 8 && z >= 0 && z <= 3;

      if (isInsideNave) {
        if (x === 7) {
          setBlock(x, SEAT_Y, z, "minecraft:smooth_stone");
        } else if ((x === 5 || x === 9) && (z === 6 || z === 9 || z === 12)) {
          setBlock(x, SEAT_Y, z, "minecraft:chiseled_stone_bricks");
        } else {
          setBlock(x, SEAT_Y, z, hash(x, SEAT_Y, z) > 0.5 ? stonePrimary : "minecraft:polished_andesite");
        }
      } else if (isPath) {
        setBlock(x, SEAT_Y, z, groundPavement);
      } else {
        setBlock(x, SEAT_Y, z, getGroundBlock(x, SEAT_Y, z));
      }
    }
  }

  // 2. CHAPEL NAVE WALLS (x: 4..10, z: 4..14, y: 6..9)
  for (let z = 4; z <= 14; z++) {
    for (let y = SEAT_Y + 1; y <= SEAT_Y + 4; y++) {
      setBlock(4, y, z, getWallStone(4, y, z));
      setBlock(10, y, z, getWallStone(10, y, z));
    }
  }

  for (let x = 4; x <= 10; x++) {
    for (let y = SEAT_Y + 1; y <= SEAT_Y + 4; y++) {
      setBlock(x, y, 4, getWallStone(x, y, 4));
      setBlock(x, y, 14, getWallStone(x, y, 14));
    }
  }

  // Slit Windows on West & East Walls
  const sideWindowZ = [6, 9, 12];
  const glassColors = [
    "minecraft:cyan_stained_glass_pane",
    "minecraft:light_blue_stained_glass_pane",
    "minecraft:blue_stained_glass_pane"
  ];

  sideWindowZ.forEach((wz, idx) => {
    const glass = glassColors[idx % glassColors.length];
    // West wall windows
    setBlock(4, SEAT_Y + 1, wz, makeStair(stoneStairs, "east", "bottom"));
    setBlock(4, SEAT_Y + 2, wz, glass);
    setBlock(4, SEAT_Y + 3, wz, glass);
    setBlock(4, SEAT_Y + 4, wz, makeStair(stoneStairs, "east", "top"));

    // East wall windows
    setBlock(10, SEAT_Y + 1, wz, makeStair(stoneStairs, "west", "bottom"));
    setBlock(10, SEAT_Y + 2, wz, glass);
    setBlock(10, SEAT_Y + 3, wz, glass);
    setBlock(10, SEAT_Y + 4, wz, makeStair(stoneStairs, "west", "top"));
  });

  // North Doorway (Entrance into Nave)
  setBlock(7, SEAT_Y + 1, 4, "minecraft:air");
  setBlock(7, SEAT_Y + 2, 4, "minecraft:air");
  setBlock(7, SEAT_Y + 3, 4, makeStair(stoneStairs, "south", "top"));
  setBlock(7, SEAT_Y + 4, 4, "minecraft:cyan_stained_glass_pane");

  // South Wall Sanctuary Lancet Windows (Altar Wall)
  setBlock(7, SEAT_Y + 2, 14, "minecraft:blue_stained_glass_pane");
  setBlock(7, SEAT_Y + 3, 14, "minecraft:cyan_stained_glass_pane");
  setBlock(7, SEAT_Y + 4, 14, "minecraft:light_blue_stained_glass_pane");
  setBlock(6, SEAT_Y + 3, 14, "minecraft:blue_stained_glass_pane");
  setBlock(8, SEAT_Y + 3, 14, "minecraft:blue_stained_glass_pane");

  // 3. BUTTRESSES (Rustic coastal stone buttresses)
  const buttressZ = [4, 7, 11, 14];
  for (const bz of buttressZ) {
    // West buttresses
    setBlock(3, SEAT_Y + 1, bz, getWallStone(3, SEAT_Y + 1, bz));
    setBlock(3, SEAT_Y + 2, bz, getWallStone(3, SEAT_Y + 2, bz));
    setBlock(3, SEAT_Y + 3, bz, makeStair(stoneStairs, "east", "bottom"));

    // East buttresses
    setBlock(11, SEAT_Y + 1, bz, getWallStone(11, SEAT_Y + 1, bz));
    setBlock(11, SEAT_Y + 2, bz, getWallStone(11, SEAT_Y + 2, bz));
    setBlock(11, SEAT_Y + 3, bz, makeStair(stoneStairs, "west", "bottom"));
  }

  // Corner Buttress Projections North/South
  setBlock(4, SEAT_Y + 1, 3, getWallStone(4, SEAT_Y + 1, 3));
  setBlock(4, SEAT_Y + 2, 3, makeStair(stoneStairs, "south", "bottom"));
  setBlock(10, SEAT_Y + 1, 3, getWallStone(10, SEAT_Y + 1, 3));
  setBlock(10, SEAT_Y + 2, 3, makeStair(stoneStairs, "south", "bottom"));

  setBlock(4, SEAT_Y + 1, 15, getWallStone(4, SEAT_Y + 1, 15));
  setBlock(4, SEAT_Y + 2, 15, makeStair(stoneStairs, "north", "bottom"));
  setBlock(10, SEAT_Y + 1, 15, getWallStone(10, SEAT_Y + 1, 15));
  setBlock(10, SEAT_Y + 2, 15, makeStair(stoneStairs, "north", "bottom"));

  // 4. NORTH PORCH & PORTAL (z = 3)
  setBlock(6, SEAT_Y + 1, 3, stoneWall);
  setBlock(6, SEAT_Y + 2, 3, stoneWall);
  setBlock(8, SEAT_Y + 1, 3, stoneWall);
  setBlock(8, SEAT_Y + 2, 3, stoneWall);
  setBlock(7, SEAT_Y + 3, 3, makeStair(stoneStairs, "south", "top"));
  setBlock(6, SEAT_Y + 3, 3, makeStair(roofStairs, "east", "bottom"));
  setBlock(8, SEAT_Y + 3, 3, makeStair(roofStairs, "west", "bottom"));
  setBlock(7, SEAT_Y + 4, 3, makeSlab(roofSlab, "bottom"));
  setBlock(7, SEAT_Y + 2, 3, "minecraft:lantern[hanging=true]");

  // 5. GABLE WALLS & GABLED ROOF
  // Gables Infill
  const gablesZ = [4, 14];
  for (const gz of gablesZ) {
    for (let gx = 5; gx <= 9; gx++) setBlock(gx, SEAT_Y + 5, gz, getWallStone(gx, SEAT_Y + 5, gz));
    for (let gx = 6; gx <= 8; gx++) {
      setBlock(gx, SEAT_Y + 6, gz, getWallStone(gx, SEAT_Y + 6, gz));
      setBlock(gx, SEAT_Y + 7, gz, getWallStone(gx, SEAT_Y + 7, gz));
    }
    setBlock(7, SEAT_Y + 8, gz, getWallStone(7, SEAT_Y + 8, gz));
  }

  // Full Gabled Slate/Stone Roof
  for (let rz = 3; rz <= 15; rz++) {
    // West slope
    setBlock(3, SEAT_Y + 4, rz, makeStair(roofStairs, "east", "bottom"));
    setBlock(3, SEAT_Y + 3, rz, makeStair(stoneStairs, "west", "top"));
    setBlock(4, SEAT_Y + 5, rz, makeStair(roofStairs, "east", "bottom"));
    setBlock(5, SEAT_Y + 6, rz, makeStair(roofStairs, "east", "bottom"));
    setBlock(6, SEAT_Y + 7, rz, makeStair(roofStairs, "east", "bottom"));

    // Central Ridge
    setBlock(7, SEAT_Y + 7, rz, roofSolid);
    setBlock(7, SEAT_Y + 8, rz, makeSlab(roofSlab, "bottom"));

    // East slope
    setBlock(8, SEAT_Y + 7, rz, makeStair(roofStairs, "west", "bottom"));
    setBlock(9, SEAT_Y + 6, rz, makeStair(roofStairs, "west", "bottom"));
    setBlock(10, SEAT_Y + 5, rz, makeStair(roofStairs, "west", "bottom"));
    setBlock(11, SEAT_Y + 4, rz, makeStair(roofStairs, "west", "bottom"));
    setBlock(11, SEAT_Y + 3, rz, makeStair(stoneStairs, "east", "top"));
  }

  // Internal Timber Rafters / Tie Beams (above standable height y >= SEAT_Y + 5)
  for (const tz of [7, 10]) {
    for (let tx = 5; tx <= 9; tx++) {
      setBlock(tx, SEAT_Y + 5, tz, makeLog(woodLog, "x"));
    }
    setBlock(7, SEAT_Y + 6, tz, woodFence);
    setBlock(7, SEAT_Y + 7, tz, woodFence);
    setBlock(6, SEAT_Y + 6, tz, woodFence);
    setBlock(8, SEAT_Y + 6, tz, woodFence);
  }

  // 6. OPEN STONE BELLCOTE (At North Gable Peak)
  setBlock(6, SEAT_Y + 8, 4, stonePrimary);
  setBlock(7, SEAT_Y + 8, 4, stonePrimary);
  setBlock(8, SEAT_Y + 8, 4, stonePrimary);

  // Twin stone pillars & open bell chamber
  setBlock(6, SEAT_Y + 9, 4, stonePrimary);
  setBlock(8, SEAT_Y + 9, 4, stonePrimary);
  setBlock(6, SEAT_Y + 10, 4, stonePrimary);
  setBlock(8, SEAT_Y + 10, 4, stonePrimary);

  setBlock(6, SEAT_Y + 9, 3, stoneWall);
  setBlock(8, SEAT_Y + 9, 3, stoneWall);

  // Bronze bell and iron chain
  setBlock(7, SEAT_Y + 10, 4, "minecraft:chain[axis=y]");
  setBlock(7, SEAT_Y + 9, 4, "minecraft:bell[attachment=ceiling,facing=north]");

  // Arch crown and stone finial cross
  setBlock(6, SEAT_Y + 11, 4, makeStair(stoneStairs, "east", "bottom"));
  setBlock(7, SEAT_Y + 11, 4, makeSlab(stoneSlab, "top"));
  setBlock(8, SEAT_Y + 11, 4, makeStair(stoneStairs, "west", "bottom"));
  setBlock(7, SEAT_Y + 12, 4, stoneWall);

  // South Gable Small Stone Cross
  setBlock(7, SEAT_Y + 9, 14, stoneWall);
  setBlock(7, SEAT_Y + 10, 14, stoneWall);

  // 7. OUTDOOR MEMORIAL CAIRNS (Dedicated to Lost Sailors)

  // Cairn 1: The Lost Fishermen's Stack (West Yard, x = 1, z = 6)
  setBlock(1, SEAT_Y + 1, 6, "minecraft:mossy_cobblestone");
  setBlock(2, SEAT_Y + 1, 6, makeStair(stoneStairs, "west", "bottom"));
  setBlock(1, SEAT_Y + 1, 7, makeStair(stoneStairs, "north", "bottom"));
  setBlock(1, SEAT_Y + 2, 6, stoneWall);
  setBlock(1, SEAT_Y + 3, 6, "minecraft:soul_lantern[hanging=false]");
  setBlock(2, SEAT_Y + 1, 7, makeSlab(stoneSlab, "bottom"));

  // Cairn 2: Mariners' Cross Cairn (West Yard, x = 1, z = 11)
  setBlock(0, SEAT_Y + 1, 11, makeStair(stoneStairs, "east", "bottom"));
  setBlock(2, SEAT_Y + 1, 11, makeStair(stoneStairs, "west", "bottom"));
  setBlock(1, SEAT_Y + 1, 10, makeStair(stoneStairs, "south", "bottom"));
  setBlock(1, SEAT_Y + 1, 12, makeStair(stoneStairs, "north", "bottom"));
  setBlock(1, SEAT_Y + 1, 11, "minecraft:cracked_stone_bricks");
  setBlock(1, SEAT_Y + 2, 11, stoneWall);
  setBlock(1, SEAT_Y + 3, 11, stoneWall);
  setBlock(1, SEAT_Y + 3, 10, stoneWall);
  setBlock(1, SEAT_Y + 3, 12, stoneWall);
  setBlock(1, SEAT_Y + 4, 11, stoneWall);

  // Cairn 3: The Widow's Beacon (East Yard, x = 13, z = 6)
  setBlock(13, SEAT_Y + 1, 5, makeStair(stoneStairs, "south", "bottom"));
  setBlock(13, SEAT_Y + 1, 7, makeStair(stoneStairs, "north", "bottom"));
  setBlock(12, SEAT_Y + 1, 6, makeStair(stoneStairs, "east", "bottom"));
  setBlock(13, SEAT_Y + 1, 6, "minecraft:chiseled_stone_bricks");
  setBlock(13, SEAT_Y + 2, 6, stoneWall);
  setBlock(13, SEAT_Y + 3, 6, "minecraft:sea_lantern");
  setBlock(13, SEAT_Y + 4, 6, makeSlab(stoneSlab, "bottom"));

  // Cairn 4: Deep Water Cenotaph (East Yard, x = 13, z = 11)
  setBlock(13, SEAT_Y + 1, 11, "minecraft:mossy_stone_bricks");
  setBlock(12, SEAT_Y + 1, 11, makeSlab(stoneSlab, "bottom"));
  setBlock(13, SEAT_Y + 1, 12, makeSlab(stoneSlab, "bottom"));
  setBlock(13, SEAT_Y + 2, 11, stoneWall);
  setBlock(12, SEAT_Y + 1, 11, "minecraft:soul_lantern[hanging=false]");

  // Cairn 5: Great Atlantic Memorial Cross (South Cliff Overlook, x = 7, z = 17)
  for (let cx = 6; cx <= 8; cx++) {
    for (let cz = 16; cz <= 17; cz++) {
      setBlock(cx, SEAT_Y + 1, cz, stonePrimary);
    }
  }
  setBlock(6, SEAT_Y + 1, 16, makeStair(stoneStairs, "south", "bottom"));
  setBlock(8, SEAT_Y + 1, 16, makeStair(stoneStairs, "south", "bottom"));
  setBlock(6, SEAT_Y + 2, 17, "minecraft:soul_lantern[hanging=false]");
  setBlock(8, SEAT_Y + 2, 17, "minecraft:soul_lantern[hanging=false]");

  setBlock(7, SEAT_Y + 2, 17, "minecraft:chiseled_stone_bricks");
  setBlock(7, SEAT_Y + 3, 17, stoneWall);
  setBlock(7, SEAT_Y + 4, 17, stoneWall);
  setBlock(6, SEAT_Y + 4, 17, stoneWall);
  setBlock(8, SEAT_Y + 4, 17, stoneWall);
  setBlock(7, SEAT_Y + 5, 17, stoneWall);

  // 8. LOW DRYSTONE BOUNDARY PARAPET
  for (let z = 2; z <= 17; z++) {
    if (z !== 8 && z !== 9) {
      setBlock(0, SEAT_Y + 1, z, hash(0, SEAT_Y, z) > 0.4 ? stoneWall : makeSlab(stoneSlab, "bottom"));
      setBlock(14, SEAT_Y + 1, z, hash(14, SEAT_Y, z) > 0.4 ? stoneWall : makeSlab(stoneSlab, "bottom"));
    }
  }
  for (let x = 1; x <= 13; x++) {
    if (x < 5 || x > 9) {
      setBlock(x, SEAT_Y + 1, 18, stoneWall);
    }
  }
  for (let x = 0; x <= 4; x++) setBlock(x, SEAT_Y + 1, 1, stoneWall);
  for (let x = 10; x <= 14; x++) setBlock(x, SEAT_Y + 1, 1, stoneWall);

  return {
    name: "chapel_for_the_drowned",
    seatY: SEAT_Y,
    anchors: {
      front: [7, SEAT_Y, 0],
      door: [7, SEAT_Y + 1, 4]
    },
    interiors: [
      {
        min: [5, SEAT_Y + 1, 5],
        max: [9, SEAT_Y + 4, 13],
        kind: "nave"
      }
    ]
  };
}

