export const envelope = [10, 14, 10];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 5;

  const rnd = () => api.random();

  // Palette extraction with safe fallbacks
  const wood = api.theme.wood || {};
  const stone = api.theme.stone || {};
  const ground = api.theme.ground || {};
  const roof = api.theme.roof || {};

  const planks = wood.planks || "minecraft:spruce_planks";
  const log = wood.log || "minecraft:spruce_log";
  const stripped = wood.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = wood.stairs || "minecraft:spruce_stairs";
  const woodSlab = wood.slab || "minecraft:spruce_slab";
  const fence = wood.fence || "minecraft:spruce_fence";
  const trapdoor = wood.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = stone.primary || "minecraft:stone_bricks";
  const stoneAccent = stone.accent || "minecraft:cobblestone";
  const stoneStairs = stone.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = stone.slab || "minecraft:stone_brick_slab";
  const stoneWall = stone.wall || "minecraft:cobblestone_wall";

  const pavement = ground.pavement || stonePrimary;
  const coping = ground.coping || stoneAccent;

  const roofStairs = roof.stairs || woodStairs;
  const roofSlab = roof.slab || woodSlab;

  // Block state modifier helpers
  function setProp(blockStr, key, val) {
    if (!blockStr) return blockStr;
    if (blockStr.includes('[')) {
      const base = blockStr.slice(0, blockStr.indexOf('['));
      const props = blockStr.slice(blockStr.indexOf('[') + 1, -1).split(',');
      const map = {};
      for (const p of props) {
        const [k, v] = p.split('=');
        map[k] = v;
      }
      map[key] = val;
      const propStr = Object.entries(map).map(([k, v]) => `${k}=${v}`).join(',');
      return `${base}[${propStr}]`;
    }
    return `${blockStr}[${key}=${val}]`;
  }

  function withAxis(blockStr, axis) {
    return setProp(blockStr, 'axis', axis);
  }

  function withFacing(blockStr, facing) {
    return setProp(blockStr, 'facing', facing);
  }

  function withHalf(blockStr, half) {
    return setProp(blockStr, 'half', half);
  }

  function safeSet(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // --- 1. QUAY PLATFORM & GROUND CONFORMITY FOUNDATION ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const h = Math.round(api.heightAt(x, z));
      const groundY = Math.max(0, Math.min(seatY, seatY + h));
      const isNorth = (z === 0);
      const isEdge = (x === 0 || x === W - 1 || z === 0 || z === D - 1);

      // Foundation downwards to terrain/seabed
      for (let y = groundY; y < seatY; y++) {
        if (isNorth) {
          if (x % 3 === 0 || x === W - 1) {
            safeSet(x, y, z, withAxis(log, 'y'));
          } else {
            safeSet(x, y, z, (y % 2 === 0) ? stonePrimary : stoneAccent);
          }
        } else if (isEdge) {
          if ((x === 0 || x === W - 1) && z % 3 === 0) {
            safeSet(x, y, z, withAxis(log, 'y'));
          } else {
            safeSet(x, y, z, stonePrimary);
          }
        } else {
          if (x % 3 === 0 && z % 3 === 0) {
            safeSet(x, y, z, withAxis(log, 'y'));
          } else {
            safeSet(x, y, z, stonePrimary);
          }
        }
      }

      // Deck at seat plane (y = seatY)
      if (isNorth) {
        safeSet(x, seatY, z, withAxis(log, 'x'));
      } else if (x === 0 || x === W - 1) {
        safeSet(x, seatY, z, withAxis(log, 'z'));
      } else {
        const deckNoise = rnd();
        if (deckNoise < 0.65) {
          safeSet(x, seatY, z, planks);
        } else if (deckNoise < 0.85) {
          safeSet(x, seatY, z, stripped);
        } else {
          safeSet(x, seatY, z, pavement);
        }
      }

      // If terrain rises above seat plane, build retaining wall up to it
      if (seatY + h > seatY) {
        const topH = Math.min(H - 1, seatY + h);
        for (let y = seatY + 1; y <= topH; y++) {
          safeSet(x, y, z, stoneAccent);
        }
      }
    }
  }

  // Quayside North Mooring Bollards
  safeSet(1, seatY + 1, 0, stoneWall);
  safeSet(1, seatY + 2, withHalf(trapdoor, 'bottom'));
  safeSet(8, seatY + 1, 0, stoneWall);
  safeSet(8, seatY + 2, withHalf(trapdoor, 'bottom'));

  // Helpers for superstructure placement
  function placePost(x, z, startY, endY) {
    for (let y = startY; y <= endY; y++) {
      safeSet(x, y, z, withAxis(log, 'y'));
    }
  }

  function placeFencePost(x, z, startY, endY) {
    for (let y = startY; y <= endY; y++) {
      safeSet(x, y, z, fence);
    }
  }

  function placeBeamX(x1, x2, y, z) {
    for (let x = x1; x <= x2; x++) {
      safeSet(x, y, z, withAxis(log, 'x'));
    }
  }

  function placeBeamZ(x, y, z1, z2) {
    for (let z = z1; z <= z2; z++) {
      safeSet(x, y, z, withAxis(log, 'z'));
    }
  }

  function placeNetCurtain(x1, z1, x2, z2, topY, botY) {
    if (x1 === x2) {
      const x = x1;
      for (let z = Math.min(z1, z2); z <= Math.max(z1, z2); z++) {
        for (let y = topY; y >= botY; y--) {
          if (rnd() > 0.12) {
            safeSet(x, y, z, "minecraft:cobweb");
          }
        }
      }
    } else if (z1 === z2) {
      const z = z1;
      for (let x = Math.min(x1, x2); x <= Math.max(x1, x2); x++) {
        for (let y = topY; y >= botY; y--) {
          if (rnd() > 0.12) {
            safeSet(x, y, z, "minecraft:cobweb");
          }
        }
      }
    }
  }

  function placeLobsterPot(x, y, z) {
    safeSet(x, y, z, "minecraft:composter[level=0]");
    safeSet(x, y + 1, withHalf(trapdoor, 'bottom'));
  }

  function placePotStack(x, z, height) {
    for (let i = 0; i < height; i++) {
      safeSet(x, seatY + 1 + i, "minecraft:composter[level=0]");
    }
    safeSet(x, seatY + 1 + height, withHalf(trapdoor, 'bottom'));
  }

  function placeBench(x1, z1, x2, z2) {
    for (let x = x1; x <= x2; x++) {
      for (let z = z1; z <= z2; z++) {
        safeSet(x, seatY + 1, stoneSlab);
      }
    }
  }

  // --- 2. INSTANCE VARIATION LOGIC ---
  const variant = api.instance.index % 8;

  if (variant === 0) {
    // VARIANT 0: High Net Tower & Derrick Crane
    placePost(1, 2, seatY + 1, seatY + 7);
    placePost(1, 7, seatY + 1, seatY + 7);
    placePost(3, 2, seatY + 1, seatY + 7);
    placePost(3, 7, seatY + 1, seatY + 7);

    placeBeamZ(1, seatY + 4, 2, 7);
    placeBeamZ(3, seatY + 4, 2, 7);
    placeBeamZ(1, seatY + 7, 2, 7);
    placeBeamZ(3, seatY + 7, 2, 7);
    placeBeamX(1, 3, seatY + 7, 2);
    placeBeamX(1, 3, seatY + 7, 7);

    // Cross A-frame ridge
    safeSet(2, seatY + 8, 2, withFacing(woodStairs, 'south'));
    safeSet(2, seatY + 8, 7, withFacing(woodStairs, 'north'));
    placeBeamZ(2, seatY + 8, 3, 6);

    // Net curtains
    placeNetCurtain(2, 3, 2, 6, seatY + 7, seatY + 2);

    // Derrick crane on East
    placePost(7, 1, seatY + 1, seatY + 6);
    safeSet(7, seatY + 6, 0, withAxis(log, 'z'));
    safeSet(7, seatY + 5, 0, withFacing(woodStairs, 'north'));
    safeSet(7, seatY + 5, 0, "minecraft:chain");
    safeSet(7, seatY + 4, 0, "minecraft:chain");
    safeSet(7, seatY + 3, 0, "minecraft:barrel[facing=up]");

    // Mending table & lobster pots
    placeBench(5, 4, 6, 5);
    safeSet(5, seatY + 2, "minecraft:lantern[hanging=false]");
    placePotStack(7, 6, 2);
    placePotStack(8, 6, 1);
    placePotStack(8, 7, 2);
    safeSet(7, seatY + 1, 7, "minecraft:barrel[facing=up]");

  } else if (variant === 1) {
    // VARIANT 1: Twin Fish-Drying Flakes & Brine Trough
    // West drying trestle
    placeFencePost(2, 2, seatY + 1, seatY + 4);
    placeFencePost(2, 4, seatY + 1, seatY + 4);
    placeFencePost(2, 6, seatY + 1, seatY + 4);
    placeFencePost(2, 7, seatY + 1, seatY + 4);
    placeBeamZ(2, seatY + 3, 2, 7);
    for (let z = 2; z <= 7; z++) {
      safeSet(2, seatY + 4, z, "minecraft:campfire[lit=false]");
    }

    // East drying trestle
    placeFencePost(7, 2, seatY + 1, seatY + 4);
    placeFencePost(7, 4, seatY + 1, seatY + 4);
    placeFencePost(7, 6, seatY + 1, seatY + 4);
    placeFencePost(7, 7, seatY + 1, seatY + 4);
    placeBeamZ(7, seatY + 3, 2, 7);
    for (let z = 2; z <= 7; z++) {
      safeSet(7, seatY + 4, z, woodSlab);
      safeSet(7, seatY + 2, z, "minecraft:cobweb");
    }

    // Central salting bench & brine trough
    placeBench(4, 3, 5, 6);
    safeSet(4, seatY + 1, 4, "minecraft:cauldron");
    safeSet(5, seatY + 1, 5, "minecraft:barrel[facing=up]");

    // South net frame
    placePost(3, 8, seatY + 1, seatY + 7);
    placePost(6, 8, seatY + 1, seatY + 7);
    placeBeamX(3, 6, seatY + 7, 8);
    placeNetCurtain(4, 8, 5, 8, seatY + 6, seatY + 2);
    safeSet(3, seatY + 8, 8, withFacing(woodStairs, 'east'));
    safeSet(6, seatY + 8, 8, withFacing(woodStairs, 'west'));

  } else if (variant === 2) {
    // VARIANT 2: Lobster Pot Depot & Bait Shed
    // Lean-to shed at South-East
    placePost(5, 5, seatY + 1, seatY + 4);
    placePost(8, 5, seatY + 1, seatY + 4);
    placePost(5, 8, seatY + 1, seatY + 6);
    placePost(8, 8, seatY + 1, seatY + 6);

    placeBeamX(5, 8, seatY + 4, 5);
    placeBeamX(5, 8, seatY + 6, 8);
    placeBeamZ(5, seatY + 5, 5, 8);
    placeBeamZ(8, seatY + 5, 5, 8);

    // Sloped roof
    for (let x = 5; x <= 8; x++) {
      safeSet(x, seatY + 5, 5, withFacing(roofStairs, 'north'));
      safeSet(x, seatY + 6, 6, withFacing(roofStairs, 'north'));
      safeSet(x, seatY + 6, 7, roofSlab);
      safeSet(x, seatY + 7, 8, roofSlab);
    }
    safeSet(6, seatY + 3, 6, "minecraft:lantern[hanging=true]");
    safeSet(6, seatY + 1, 7, "minecraft:dried_kelp_block");
    safeSet(7, seatY + 1, 7, "minecraft:barrel[facing=up]");

    // Massive stacks of wicker lobster pots on West
    placePotStack(1, 4, 3);
    placePotStack(2, 4, 2);
    placePotStack(1, 5, 2);
    placePotStack(2, 5, 3);
    placePotStack(1, 6, 2);
    placePotStack(2, 6, 1);
    placePotStack(3, 5, 1);
    placePotStack(3, 6, 2);
    placePotStack(2, 7, 1);

    // Buoy pole
    placeFencePost(1, 2, seatY + 1, seatY + 6);
    safeSet(1, seatY + 7, 2, "minecraft:lantern[hanging=false]");

    // North mending rail
    placeFencePost(3, 1, seatY + 1, seatY + 3);
    placeFencePost(5, 1, seatY + 1, seatY + 3);
    placeBeamX(3, 5, seatY + 3, 1);
    placeNetCurtain(3, 1, 5, 1, seatY + 2, seatY + 1);

  } else if (variant === 3) {
    // VARIANT 3: Smoker Hearth & Curing Flakes
    // Stone smoker hearth at South
    for (let x = 4; x <= 6; x++) {
      for (let z = 7; z <= 8; z++) {
        safeSet(x, seatY + 1, z, stonePrimary);
      }
    }
    safeSet(5, seatY + 1, 7, "minecraft:campfire[lit=false]");
    safeSet(4, seatY + 2, 7, stoneWall);
    safeSet(6, seatY + 2, 7, stoneWall);
    safeSet(4, seatY + 2, 8, stonePrimary);
    safeSet(6, seatY + 2, 8, stonePrimary);
    safeSet(5, seatY + 2, 8, stonePrimary);

    // Chimney
    placePost(5, 8, seatY + 3, seatY + 6);
    safeSet(5, seatY + 7, 8, "minecraft:campfire[lit=false]");
    safeSet(5, seatY + 8, 8, withHalf(trapdoor, 'bottom'));

    // Overhead curing trestles
    placePost(2, 4, seatY + 1, seatY + 7);
    placePost(7, 4, seatY + 1, seatY + 7);
    placePost(2, 6, seatY + 1, seatY + 7);
    placePost(7, 6, seatY + 1, seatY + 7);

    placeBeamX(2, 7, seatY + 4, 4);
    placeBeamX(2, 7, seatY + 4, 6);
    placeBeamX(2, 7, seatY + 7, 4);
    placeBeamX(2, 7, seatY + 7, 6);
    placeBeamZ(2, seatY + 7, 4, 6);
    placeBeamZ(7, seatY + 7, 4, 6);

    placeNetCurtain(3, 5, 6, 5, seatY + 6, seatY + 2);

    // Gutting bench on West
    placeBench(1, 3, 2, 5);
    safeSet(1, seatY + 1, 4, "minecraft:cauldron");
    safeSet(2, seatY + 2, 3, "minecraft:lantern[hanging=false]");

    // Crates and pots
    placePotStack(7, 2, 2);
    placePotStack(8, 2, 1);
    safeSet(8, seatY + 1, 3, "minecraft:barrel[facing=up]");

  } else if (variant === 4) {
    // VARIANT 4: Angled Net Hurdle Platform & Yardarm Mast
    // Slanted hurdles on West (stepped up from Z=2 to Z=7)
    for (let x = 1; x <= 4; x++) {
      safeSet(x, seatY + 1, 2, woodStairs);
      safeSet(x, seatY + 1, 3, planks);
      safeSet(x, seatY + 2, 4, woodStairs);
      safeSet(x, seatY + 2, 5, planks);
      safeSet(x, seatY + 3, 6, woodStairs);
      safeSet(x, seatY + 3, 7, planks);

      // Nets spread across hurdles
      safeSet(x, seatY + 2, 3, "minecraft:cobweb");
      safeSet(x, seatY + 3, 5, "minecraft:cobweb");
      safeSet(x, seatY + 4, 7, "minecraft:cobweb");
    }

    // Yardarm Mast on East
    placePost(8, 3, seatY + 1, seatY + 8);
    placeBeamZ(8, seatY + 7, 1, 6);
    safeSet(8, seatY + 6, 1, withFacing(woodStairs, 'north'));
    safeSet(8, seatY + 6, 6, withFacing(woodStairs, 'south'));

    // Rigging & net curtains from yardarm
    placeNetCurtain(7, 2, 7, 5, seatY + 6, seatY + 2);
    safeSet(8, seatY + 6, 1, "minecraft:chain");
    safeSet(8, seatY + 5, 1, "minecraft:chain");
    safeSet(8, seatY + 4, 1, "minecraft:lantern[hanging=true]");

    // Lobster pots & rope crates
    placePotStack(6, 7, 2);
    placePotStack(7, 7, 3);
    placePotStack(8, 7, 2);
    placePotStack(7, 6, 1);
    safeSet(6, seatY + 1, 6, "minecraft:hay_block");

  } else if (variant === 5) {
    // VARIANT 5: Mender's Loft Canopy & Tiered Herring Flakes
    // Canopy on North-West
    placePost(1, 1, seatY + 1, seatY + 4);
    placePost(4, 1, seatY + 1, seatY + 4);
    placePost(1, 4, seatY + 1, seatY + 5);
    placePost(4, 4, seatY + 1, seatY + 5);

    placeBeamX(1, 4, seatY + 4, 1);
    placeBeamX(1, 4, seatY + 5, 4);
    placeBeamZ(1, seatY + 4, 1, 4);
    placeBeamZ(4, seatY + 4, 1, 4);

    for (let x = 1; x <= 4; x++) {
      safeSet(x, seatY + 5, 1, withFacing(roofStairs, 'north'));
      safeSet(x, seatY + 5, 2, roofSlab);
      safeSet(x, seatY + 6, 3, withFacing(roofStairs, 'north'));
      safeSet(x, seatY + 6, 4, roofSlab);
    }
    placeBench(2, 2, 3, 3);
    safeSet(2, seatY + 3, 2, "minecraft:lantern[hanging=true]");

    // Tiered herring racks on East
    placePost(7, 2, seatY + 1, seatY + 7);
    placePost(7, 5, seatY + 1, seatY + 7);
    placePost(7, 8, seatY + 1, seatY + 7);

    placeBeamZ(7, seatY + 3, 2, 8);
    placeBeamZ(7, seatY + 5, 2, 8);
    placeBeamZ(7, seatY + 7, 2, 8);

    for (let z = 2; z <= 8; z++) {
      if (z !== 5) {
        safeSet(7, seatY + 2, z, "minecraft:cobweb");
        safeSet(7, seatY + 4, z, woodSlab);
        safeSet(7, seatY + 6, z, "minecraft:campfire[lit=false]");
      }
    }

    // Lobster pots at South-West
    placePotStack(1, 6, 2);
    placePotStack(2, 6, 3);
    placePotStack(1, 7, 1);
    placePotStack(2, 7, 2);
    safeSet(3, seatY + 1, 7, "minecraft:barrel[facing=up]");

  } else if (variant === 6) {
    // VARIANT 6: Twin Giant A-Frames with Net Curtains
    // West Gantry
    placePost(2, 1, seatY + 1, seatY + 7);
    placePost(2, 4, seatY + 1, seatY + 7);
    placePost(2, 8, seatY + 1, seatY + 7);
    placeBeamZ(2, seatY + 7, 1, 8);

    // East Gantry
    placePost(7, 1, seatY + 1, seatY + 7);
    placePost(7, 4, seatY + 1, seatY + 7);
    placePost(7, 8, seatY + 1, seatY + 7);
    placeBeamZ(7, seatY + 7, 1, 8);

    // Cross spans bridging West & East
    placeBeamX(2, 7, seatY + 6, 2);
    placeBeamX(2, 7, seatY + 6, 5);
    placeBeamX(2, 7, seatY + 6, 8);

    // Diagonal A-frame ridge caps
    safeSet(2, seatY + 8, 1, withFacing(woodStairs, 'south'));
    safeSet(2, seatY + 8, 8, withFacing(woodStairs, 'north'));
    safeSet(7, seatY + 8, 1, withFacing(woodStairs, 'south'));
    safeSet(7, seatY + 8, 8, withFacing(woodStairs, 'north'));

    // Net curtains suspended between spans
    placeNetCurtain(4, 2, 5, 2, seatY + 5, seatY + 2);
    placeNetCurtain(4, 5, 5, 5, seatY + 5, seatY + 2);
    placeNetCurtain(4, 8, 5, 8, seatY + 5, seatY + 2);
    placeNetCurtain(2, 3, 2, 7, seatY + 6, seatY + 2);
    placeNetCurtain(7, 3, 7, 7, seatY + 6, seatY + 2);

    // Work alleyway in center
    placeBench(4, 3, 5, 4);
    safeSet(4, seatY + 1, 3, "minecraft:cauldron");
    safeSet(5, seatY + 2, 4, "minecraft:lantern[hanging=false]");
    placePotStack(4, 6, 2);
    placePotStack(5, 6, 1);
    placePotStack(5, 7, 2);

  } else {
    // VARIANT 7: Harbour Corner Gear Depot & Flake Terrace
    // Derrick crane on Northeast
    placePost(8, 2, seatY + 1, seatY + 8);
    placeBeamX(5, 8, seatY + 7, 2);
    safeSet(5, seatY + 6, 2, withFacing(woodStairs, 'west'));
    safeSet(5, seatY + 6, 1, "minecraft:chain");
    safeSet(5, seatY + 5, 1, "minecraft:chain");
    safeSet(5, seatY + 4, 1, "minecraft:barrel[facing=up]");

    // Multi-tier flake terrace on West
    placePost(1, 2, seatY + 1, seatY + 7);
    placePost(3, 2, seatY + 1, seatY + 7);
    placePost(1, 6, seatY + 1, seatY + 7);
    placePost(3, 6, seatY + 1, seatY + 7);

    placeBeamZ(1, seatY + 3, 2, 6);
    placeBeamZ(3, seatY + 3, 2, 6);
    placeBeamZ(1, seatY + 5, 2, 6);
    placeBeamZ(3, seatY + 5, 2, 6);
    placeBeamZ(1, seatY + 7, 2, 6);
    placeBeamZ(3, seatY + 7, 2, 6);

    placeNetCurtain(2, 2, 2, 6, seatY + 6, seatY + 2);

    // Central salting bench
    placeBench(4, 4, 5, 5);
    safeSet(4, seatY + 2, 4, "minecraft:lantern[hanging=false]");

    // South lobster pot pyramid
    placePotStack(6, 6, 3);
    placePotStack(7, 6, 2);
    placePotStack(8, 6, 2);
    placePotStack(6, 7, 2);
    placePotStack(7, 7, 3);
    placePotStack(8, 7, 1);
    safeSet(5, seatY + 1, 7, "minecraft:barrel[facing=up]");
    safeSet(5, seatY + 1, 6, "minecraft:dried_kelp_block");
  }

  return {
    name: "drying_racks_and_net_frames",
    seatY: 5,
    anchors: {
      front: [Math.floor(W / 2), seatY, 0]
    }
  };
}
